return {["fb400_01"]={["down"]=[[fb400_02]],["dsc"]=[[迎面一阵微风吹来，风中似乎带有阵阵花香，令人心旷神怡。再往前路已至尽头，一扇铜门半开，将门后的景象半遮半掩。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb400_01]],["item1"]=[[wp01]],["name"]=[[铜门]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_02"]={["down"]=[[fb400_04]],["dsc"]=[[绕过铜门，眼前是一座美轮美奂的阁楼，一缕缕阳光从墙上的花砖缝隙里透射进来，在青砖地上投下别致的光影，如同一格格棋盘相似。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb400_02]],["item1"]=[[wp02]],["name"]=[[红楼]],["permission"]=1,["role1"]=[[drnpc01a]],["role2"]=[[drnpc02a]],["role3"]=[[drnpc03a]],["stepMusic"]=[[mudiban]],["up"]=[[fb400_01]]},["fb400_03"]={["dsc"]=[[这是一片荒凉的土地。站在此地，阵阵阴风吹来，时不时还有几声狼嚎，挑战着来往者敏感的神经。]],["fightBackground"]=[[山内]],["id"]=[[fb400_03]],["item1"]=[[wp03]],["name"]=[[荒地]],["permission"]=1,["right"]=[[fb400_04]],["stepMusic"]=[[jiaobu]]},["fb400_04"]={["dsc"]=[[后山上到处是一株株巨大无比的松树。遥遥看去， 好似一座座松树之墙耸立其中，将后山道道围起，让人瘆得发慌。]],["fightBackground"]=[[山内]],["id"]=[[fb400_04]],["left"]=[[fb400_03]],["name"]=[[后山]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_02]]},["fb400_05"]={["down"]=[[fb400_06]],["dsc"]=[[这里是村子的村口，往山上走便可以看到村子的全貌。村子不大，有几间土坯泥房，看来村中人家不多，而且大都生活很艰辛。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_05]],["item1"]=[[wp01]],["name"]=[[村口]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_06"]={["down"]=[[fb400_08]],["dsc"]=[[这里是一条上山的小路，周围平静得出奇，搞得你颇有些紧张。]],["fightBackground"]=[[山内]],["id"]=[[fb400_06]],["name"]=[[小路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_05]]},["fb400_07"]={["dsc"]=[[这里是一间破烂的泥砖屋，虽然简陋，可是东西摆放的很整齐，看得出屋子的主人虽然生活困苦，但也还在认真对待生活。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_07]],["name"]=[[民居]],["permission"]=1,["right"]=[[fb400_08]],["role1"]=[[drnpc04]],["stepMusic"]=[[jiaobu]]},["fb400_08"]={["down"]=[[fb400_11]],["dsc"]=[[这里是一条上山的小路，周围平静得出奇，搞得你颇有些紧张。]],["fightBackground"]=[[山内]],["id"]=[[fb400_08]],["left"]=[[fb400_07]],["name"]=[[小路]],["permission"]=1,["right"]=[[fb400_09]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_06]]},["fb400_09"]={["dsc"]=[[这里是一间破烂的泥砖屋，虽然简陋，可是东西摆放的很整齐，看得出屋子的主人虽然生活困苦，但也还在认真对待生活。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_09]],["item1"]=[[wp04]],["left"]=[[fb400_08]],["name"]=[[民居]],["permission"]=1,["role1"]=[[drnpc05a]],["stepMusic"]=[[jiaobu]]},["fb400_10"]={["dsc"]=[[这里是一间破烂的泥砖屋，虽然简陋，可是东西摆放的很整齐，看得出屋子的主人虽然生活困苦，但也还在认真对待生活。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_10]],["name"]=[[民居]],["permission"]=1,["right"]=[[fb400_11]],["role1"]=[[drnpc06a]],["stepMusic"]=[[jiaobu]]},["fb400_11"]={["down"]=[[fb400_12]],["dsc"]=[[这是一条通往山上的泥路，你脚下滑滑的，很不好走，不知道这条路是通向哪里的，也没有人修一修。]],["fightBackground"]=[[山内]],["id"]=[[fb400_11]],["left"]=[[fb400_10]],["name"]=[[山路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_08]]},["fb400_12"]={["down"]=[[fb400_15]],["dsc"]=[[这是一条通往山上的泥路，你脚下滑滑的，很不好走，不知道这条路是通向哪里的，也没有人修一修。]],["fightBackground"]=[[山内]],["id"]=[[fb400_12]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb400_13]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_11]]},["fb400_13"]={["dsc"]=[[这是一条通往山上的泥路，你脚下滑滑的，很不好走，不知道这条路是通向哪里的，也没有人修一修。]],["fightBackground"]=[[山内]],["id"]=[[fb400_13]],["left"]=[[fb400_12]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb400_14]],["stepMusic"]=[[jiaobu]]},["fb400_14"]={["dsc"]=[[一座富丽堂皇的大宅院出现在你的眼前，两头高大的石狮子镇住了大门两侧，朱漆大门足足有三寸厚。门上挂着两个灯笼，上面写着两个“戚”字...]],["fightBackground"]=[[城镇室外]],["id"]=[[fb400_14]],["item1"]=[[wp05]],["item2"]=[[wp06]],["item3"]=[[wp07]],["item4"]=[[wp08a]],["left"]=[[fb400_13]],["name"]=[[戚家宅院]],["permission"]=1,["role1"]=[[drnpc07a]],["stepMusic"]=[[jiaobu]]},["fb400_15"]={["dsc"]=[[越往上走，山路越陡。一阵微风吹来，一旁的树沙沙作响，仿佛在说悄悄话。]],["fightBackground"]=[[山内]],["id"]=[[fb400_15]],["name"]=[[山顶]],["permission"]=1,["right"]=[[fb400_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_12]]},["fb400_16"]={["dsc"]=[[一座年久失修的破庙，神像早已毁坏。到处荒草丛生，断壁残垣，一片破败的景象。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_16]],["left"]=[[fb400_15]],["name"]=[[破庙]],["permission"]=1,["role1"]=[[drnpc08a]],["stepMusic"]=[[jiaobu]]},["fb400_17"]={["down"]=[[fb400_18]],["dsc"]=[[一个贮藏粮食的粮仓。整个粮仓似是由废弃的庙宇、祠堂改造而成的。外表看上去十分简陋，却有完整的门窗、通气孔、出粮口、防鼠和防潮结构。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_17]],["name"]=[[粮仓]],["permission"]=1,["role1"]=[[drnpc13a]],["stepMusic"]=[[jiaobu]]},["fb400_18"]={["down"]=[[fb400_19]],["dsc"]=[[这是僻静的后院，水池的两旁种满了花草。东边是一棵槐树，郁郁葱葱，遮盖了大半个院子，显得阴森恐怖。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_18]],["item1"]=[[wp12]],["name"]=[[苗家寨后院]],["permission"]=1,["role1"]=[[drnpc12a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_17]]},["fb400_19"]={["down"]=[[fb400_22]],["dsc"]=[[这里是苗家寨居民日常生活的地方。农舍、牲畜棚圈、仓库场院、道路、水渠、宅旁绿地，这里应有尽有。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb400_19]],["item1"]=[[wp19]],["item2"]=[[wp20]],["name"]=[[苗家聚落]],["permission"]=1,["right"]=[[fb400_20]],["stepMusic"]=[[mudiban]],["up"]=[[fb400_18]]},["fb400_20"]={["dsc"]=[[这里是一间卧房，室内一床一几，陈设简单，床上挂了纱帐，甚是陈旧，已呈黄色。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb400_20]],["left"]=[[fb400_19]],["name"]=[[寨主卧室]],["permission"]=1,["role1"]=[[drnpc11a]],["stepMusic"]=[[mudiban]]},["fb400_21"]={["down"]=[[fb400_23]],["dsc"]=[[这里是一间破烂的泥砖屋，虽然简陋，可是东西摆放的很整齐，看得出屋子的主人虽然生活困苦，但也还在认真对待生活。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_21]],["name"]=[[山间民居]],["permission"]=1,["role1"]=[[drnpc10a]],["stepMusic"]=[[jiaobu]]},["fb400_22"]={["down"]=[[fb400_24]],["dsc"]=[[这里是苗族营寨的寨口，守备森严。寨口两边各插着一面大旗，上面写着“苗家寨”三个大字。四面设有木栅围栏，防护得十分周全。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_22]],["item1"]=[[wp17]],["item2"]=[[wp18]],["name"]=[[苗家寨口]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_19]]},["fb400_23"]={["down"]=[[fb400_27]],["dsc"]=[[此山并不算高，而登山之路则在其山脊之上，山路崎岖难行，两侧脊坡光滑挺拔，若有失足，便可能摔落山崖。]],["fightBackground"]=[[山内]],["id"]=[[fb400_23]],["name"]=[[山脊]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_21]]},["fb400_24"]={["dsc"]=[[山势逐级升高，不知是谁在此建造了石阶，拾阶而上，便可踏入山门，通往后方。]],["fightBackground"]=[[山内]],["id"]=[[fb400_24]],["item1"]=[[wp17]],["item2"]=[[wp18]],["name"]=[[山门]],["permission"]=1,["right"]=[[fb400_25]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_22]]},["fb400_25"]={["dsc"]=[[在这里能看到零星生着的几棵松树，数蓬野草。远处水声淙淙，似乎有条山溪。 而此处则是一条曲曲折折的山道。]],["fightBackground"]=[[山内]],["id"]=[[fb400_25]],["left"]=[[fb400_24]],["name"]=[[山道]],["permission"]=1,["right"]=[[fb400_26]],["stepMusic"]=[[jiaobu]]},["fb400_26"]={["dsc"]=[[在这里能看到零星生着的几棵松树，数蓬野草。远处水声淙淙，似乎有条山溪。 而此处则是一条曲曲折折的山道。]],["fightBackground"]=[[山内]],["id"]=[[fb400_26]],["left"]=[[fb400_25]],["name"]=[[山道]],["permission"]=1,["right"]=[[fb400_27]],["stepMusic"]=[[jiaobu]]},["fb400_27"]={["down"]=[[fb400_29]],["dsc"]=[[此山并不算高，而登山之路则在其山脊之上，山路崎岖难行，两侧脊坡光滑挺拔，若有失足，便可能摔落山崖。]],["fightBackground"]=[[山内]],["id"]=[[fb400_27]],["left"]=[[fb400_26]],["name"]=[[山脊]],["permission"]=1,["right"]=[[fb400_28]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_23]]},["fb400_28"]={["dsc"]=[[这里是一间破烂的泥砖屋，虽然简陋，可是东西摆放的很整齐，看得出屋子的主人虽然生活困苦，但也还在认真对待生活。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb400_28]],["item1"]=[[wp13]],["item2"]=[[wp14]],["left"]=[[fb400_27]],["name"]=[[山间民居]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_29"]={["down"]=[[fb400_30]],["dsc"]=[[一条未经开发的小路，旁边的灌木，已经被人破坏得不成样子，如果你不小心碰到灌木枝上，就可能会刺出血来。]],["fightBackground"]=[[森林外]],["id"]=[[fb400_29]],["name"]=[[林中小道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_27]]},["fb400_30"]={["down"]=[[fb400_31]],["dsc"]=[[一条未经开发的小路，旁边的灌木，已经被人破坏得不成样子，如果你不小心碰到灌木枝上，就可能会刺出血来。]],["fightBackground"]=[[森林外]],["id"]=[[fb400_30]],["name"]=[[林中小道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_29]]},["fb400_31"]={["dsc"]=[[一条未经开发的小路，旁边的灌木，已经被人破坏得不成样子，如果你不小心碰到灌木枝上，就可能会刺出血来。]],["fightBackground"]=[[森林外]],["id"]=[[fb400_31]],["item1"]=[[wp01]],["name"]=[[林中小道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_30]]},["fb400_32"]={["down"]=[[fb400_34]],["dsc"]=[[门钉门环俱以白骨做成，年代久远，白骨变黄，泛出渗人光泽。门板以棺椁改造，系上古巨灵神的石棺棺盖，日久天长，有阴灵自生，常桀桀怪笑。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_32]],["item1"]=[[wp01]],["name"]=[[黄泉府门]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_33"]={["dsc"]=[[杀母取婴愈千人，以母婴精血为引子，封怨灵于其中，腥气逼人，视之胆寒。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_33]],["name"]=[[招魂赤幡]],["permission"]=1,["right"]=[[fb400_34]],["stepMusic"]=[[jiaobu]]},["fb400_34"]={["down"]=[[fb400_37]],["dsc"]=[[幽深不见底，水汽寒意逼人，鸿毛不浮，水中不时传来凄厉啼声，令人毛骨悚然。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_34]],["left"]=[[fb400_33]],["name"]=[[幽冥暗河]],["permission"]=1,["right"]=[[fb400_35]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_32]]},["fb400_35"]={["dsc"]=[[取千年古墓尸水辅以僵尸利齿练成，碧光磷磷，奇毒无比。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_35]],["left"]=[[fb400_34]],["name"]=[[招魂青幡]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_36"]={["dsc"]=[[取三生河畔池水辅以阴年阴时阴月阴日女子情泪练成，可令人忘记前生今世，成为傀儡。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_36]],["name"]=[[招魂白幡]],["permission"]=1,["right"]=[[fb400_37]],["stepMusic"]=[[jiaobu]]},["fb400_37"]={["down"]=[[fb400_40]],["dsc"]=[[幽深不见底，水汽寒意逼人，鸿毛不浮，水中不时传来凄厉啼声，令人毛骨悚然。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_37]],["left"]=[[fb400_36]],["name"]=[[幽冥暗河]],["permission"]=1,["right"]=[[fb400_38]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_34]]},["fb400_38"]={["dsc"]=[[取无底洞壁幽草辅以混沌之气炼成，挥动此幡可遮天蔽日，令天地失色，日月无光。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_38]],["left"]=[[fb400_37]],["name"]=[[招魂黑幡]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_39"]={["dsc"]=[[取黄泉孤魂辅以息土炼成，用之可令海水倒灌，黄河决堤。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_39]],["name"]=[[招魂黄幡]],["permission"]=1,["right"]=[[fb400_40]],["stepMusic"]=[[jiaobu]]},["fb400_40"]={["down"]=[[fb400_43]],["dsc"]=[[幽深不见底，水汽寒意逼人，鸿毛不浮，水中不时传来凄厉啼声，令人毛骨悚然。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_40]],["left"]=[[fb400_39]],["name"]=[[幽冥暗河]],["permission"]=1,["right"]=[[fb400_41]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_37]]},["fb400_41"]={["down"]=[[fb400_44]],["dsc"]=[[灵魂往生之处，常有孤魂野鬼徘徊其间不得投胎，哭声凄厉，鬼气森森，令人胆寒。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_41]],["left"]=[[fb400_40]],["name"]=[[轮回台]],["permission"]=1,["right"]=[[fb400_42]],["role1"]=[[drnpc14a]],["stepMusic"]=[[jiaobu]]},["fb400_42"]={["dsc"]=[[无常阁摆设独特，一侧挂白纱帐，以兽骨作装饰，乃至床榻倚靠处也是一具巨大的骨架。另一侧则挂黑纱帐，桌椅皆上黑漆。中间二色交融，放黑白花架，符纸满地。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_42]],["left"]=[[fb400_41]],["name"]=[[无常阁]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb400_43"]={["down"]=[[fb400_45]],["dsc"]=[[幽深不见底，水汽寒意逼人，鸿毛不浮，水中不时传来凄厉啼声，令人毛骨悚然。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_43]],["name"]=[[幽冥暗河]],["permission"]=1,["right"]=[[fb400_44]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_40]]},["fb400_44"]={["dsc"]=[[专为折磨叛徒、重犯而设，为了震慑教中弟子，往往对受刑者无所不为，受刑者多死相凄惨。据说堂内共有九千九百种酷刑，其酷烈更胜地狱。凡入此堂，十死无生。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_44]],["left"]=[[fb400_43]],["name"]=[[炼狱堂]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb400_41]]},["fb400_45"]={["dsc"]=[[弟子试炼之所，多以战养战、试炼蛊法，令弟子自相残杀，在生死搏斗间提升实力，选出其中优秀者，场面惨不忍睹，故此间弟子十不存一。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb400_45]],["name"]=[[幽冥鬼府]],["permission"]=1,["role1"]=[[drnpc15a]],["role2"]=[[drnpc16a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb400_43]]},["fb400_46"]={["dsc"]=[[马车徐徐驶过，声音寂寥而单调，拉车的马只有两匹，形体俊美而健壮，马蹄嘚嘚敲击着地面，溅起阵阵沙雾。]],["fightBackground"]=[[森林外]],["id"]=[[fb400_46]],["name"]=[[马车]],["permission"]=1,["role1"]=[[drnpc17a]],["stepMusic"]=[[jiaobu]]}}0000000